import {MODULE_ID} from '../../framework/constants.js';

/**
 * Bacterial Barrage (SCGtD cantrip) — a ranged spell attack that deals necrotic
 * damage. If the target is already Poisoned (or carries a GM-defined "disease"
 * effect), the necrotic damage die grows from Nd8 to Nd12.
 *
 * This runs at the damage step on the caster's own client: it reads the current
 * attack target's conditions (a plain replicated read — no ownership needed) and,
 * when the target qualifies, rewrites the caster's own damage card from Nd8 to
 * Nd12 before vanilla dnd5e applies it (the d12 formula is visible on the card).
 * If the roll is not the expected d8 pool it is left untouched.
 *
 * "Disease" has no canonical dnd5e status, so it is matched by configurable
 * effect-name substring (default "disease"). If no target is selected the roll is
 * left at 1d8.
 *
 * Per-item settings (Manage Automations on the spell):
 *   - countDisease: also upgrade the die when the target has a disease-flagged
 *     effect (in addition to the Poisoned condition).
 *   - diseaseKeyword: substring matched (case-insensitive) against the target's
 *     effect names / statuses to count as "disease".
 */

/** Resolve the single attack target on the acting client, if any. */
function currentTarget() {
    const targets = Array.from(game.user?.targets ?? []);
    return targets[0]?.actor ?? null;
}

/**
 * Does this actor count as poisoned or (optionally) diseased?
 * Reading a target's conditions/effects is a replicated read — always safe.
 */
function isAfflicted(actor, {countDisease, diseaseKeyword}) {
    if (!actor) return {afflicted: false, reason: ''};

    const poisonedId = CONFIG.statusEffects?.find?.(status => status.id === 'poisoned')?.id
        ?? 'poisoned';
    const statuses = actor.statuses ?? new Set();
    if (statuses.has(poisonedId) || statuses.has('poisoned')) {
        return {afflicted: true, reason: 'Poisoned'};
    }

    if (!countDisease) return {afflicted: false, reason: ''};

    const needle = (diseaseKeyword ?? '').toLowerCase().trim();
    if (!needle) return {afflicted: false, reason: ''};

    // Match the keyword against active-effect names and any status ids/labels.
    for (const effect of actor.appliedEffects ?? actor.effects ?? []) {
        if ((effect.name ?? '').toLowerCase().includes(needle)) {
            return {afflicted: true, reason: 'Diseased'};
        }
        for (const status of effect.statuses ?? []) {
            if (String(status).toLowerCase().includes(needle)) {
                return {afflicted: true, reason: 'Diseased'};
            }
        }
    }
    for (const status of statuses) {
        if (String(status).toLowerCase().includes(needle)) {
            return {afflicted: true, reason: 'Diseased'};
        }
    }
    return {afflicted: false, reason: ''};
}

/**
 * Rewrite a d8-pool necrotic roll to the same number of d12s.
 * Returns a new evaluated DamageRoll, or null if the roll isn't a plain Nd8.
 */
async function upgradeToD12(roll) {
    // Only rewrite a straightforward Nd8 pool; anything with extra terms or a
    // different denomination is left alone so we never mangle a modified roll.
    const dieTerms = (roll.terms ?? []).filter(term => term instanceof foundry.dice.terms.Die);
    const otherTerms = (roll.terms ?? []).filter(term =>
        !(term instanceof foundry.dice.terms.Die)
        && !(term instanceof foundry.dice.terms.OperatorTerm));
    if (dieTerms.length !== 1 || otherTerms.length) return null;
    const die = dieTerms[0];
    if (die.faces !== 8) return null;

    const DamageRoll = CONFIG.Dice?.DamageRoll ?? Roll;
    const type = roll.options?.type ?? roll.terms?.[0]?.options?.flavor;
    const upgraded = new DamageRoll(`${die.number}d12`, roll.data ?? {}, {...roll.options, type});
    return upgraded.evaluate();
}

// Only the acting client (the caster) runs this; it only rewrites the caster's
// own damage card and only reads — never writes — the target's data.
async function damage(context) {
    if (!context.damageRolls?.length) return;
    const settings = context.settings ?? {};
    const opts = {
        countDisease: settings.countDisease ?? false,
        diseaseKeyword: settings.diseaseKeyword ?? 'disease'
    };

    // Never block the roll — no target, leave the d8 as-is.
    const target = currentTarget();
    if (!target) return;

    const {afflicted} = isAfflicted(target, opts);
    if (!afflicted) return; // the d8 is correct

    // Upgrade only the necrotic d8 pool(s); pass any other rolls through unchanged.
    const newRolls = [];
    let upgradedAny = false;
    for (const roll of context.damageRolls) {
        const upgraded = await upgradeToD12(roll);
        if (upgraded) {
            newRolls.push(upgraded);
            upgradedAny = true;
        } else {
            newRolls.push(roll);
        }
    }

    // Not a plain Nd8 — leave the card unchanged rather than mangle a modified roll.
    if (!upgradedAny) return;

    await context.setDamageRolls(newRolls);

    // Reflect the new roll with Dice So Nice if it's active.
    if (game.dice3d) {
        for (const roll of newRolls) {
            await game.dice3d.showForRoll(roll, game.user, true).catch(() => {});
        }
    }
}

